import{_ as e,o as c,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Almacenamiento en Caché","description":"","frontmatter":{},"headers":[],"relativePath":"es/advanced/caching.md","filePath":"es/advanced/caching.md","lastUpdated":1784903584000}'),s={name:"es/advanced/caching.md"};function t(o,a,r,l,d,h){return c(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="almacenamiento-en-cache" tabindex="-1">Almacenamiento en Caché <a class="header-anchor" href="#almacenamiento-en-cache" aria-label="Permalink to &quot;Almacenamiento en Caché&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>swag2mcp almacena en caché los archivos de especificación descargados para que el servidor MCP se inicie más rápido en ejecuciones posteriores. En lugar de descargar el mismo archivo de especificación cada vez, reutiliza la copia en caché.</p><h2 id="como-funciona-el-almacenamiento-en-cache" tabindex="-1">Cómo funciona el almacenamiento en caché <a class="header-anchor" href="#como-funciona-el-almacenamiento-en-cache" aria-label="Permalink to &quot;Cómo funciona el almacenamiento en caché&quot;">​</a></h2><p>Cuando agrega una especificación con una URL remota, swag2mcp la descarga y la guarda en el directorio <code>cache/</code>. En el siguiente inicio, verifica si la copia en caché sigue siendo válida. Si lo es, se omite la descarga.</p><h3 id="que-se-almacena-en-cache" tabindex="-1">Qué se almacena en caché <a class="header-anchor" href="#que-se-almacena-en-cache" aria-label="Permalink to &quot;Qué se almacena en caché&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Origen</th><th>Comportamiento</th></tr></thead><tbody><tr><td><strong>URL remota</strong> (http/https)</td><td>Siempre se almacena en caché. Se descarga una vez, se reutiliza hasta que la caché expire.</td></tr><tr><td><strong>Archivo local en <code>specs/</code></strong></td><td>Se usa directamente desde el directorio <code>specs/</code>. Nunca se almacena en caché — los cambios son inmediatamente visibles.</td></tr><tr><td><strong>Archivo local fuera de <code>specs/</code></strong></td><td>Se copia a la caché. Si el archivo fuente cambia (hora de modificación), la caché se invalida.</td></tr></tbody></table><h3 id="expiracion-de-la-cache-ttl" tabindex="-1">Expiración de la caché (TTL) <a class="header-anchor" href="#expiracion-de-la-cache-ttl" aria-label="Permalink to &quot;Expiración de la caché (TTL)&quot;">​</a></h3><p>Cada archivo en caché recibe un tiempo de expiración aleatorio entre <strong>1 hora y 48 horas</strong>. La aleatoriedad evita que todos los archivos en caché expiren al mismo tiempo (lo que causaría una avalancha de descargas).</p><ul><li>El TTL se restablece cada vez que se inicia el servidor MCP</li><li>Si un archivo en caché aún está dentro de su TTL, se reutiliza</li><li>Si el TTL ha expirado, el archivo se descarga nuevamente</li></ul><h3 id="estructura-de-la-cache" tabindex="-1">Estructura de la caché <a class="header-anchor" href="#estructura-de-la-cache" aria-label="Permalink to &quot;Estructura de la caché&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # Archivo de especificación en caché</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # Metadatos (origen, TTL, momento de almacenamiento)</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>La clave de caché se deriva de la URL o ruta del archivo de especificación. Cada archivo en caché tiene un archivo <code>.meta</code> acompañante que almacena cuándo se almacenó en caché y cuándo expira.</p><h2 id="gestion-de-la-cache" tabindex="-1">Gestión de la caché <a class="header-anchor" href="#gestion-de-la-cache" aria-label="Permalink to &quot;Gestión de la caché&quot;">​</a></h2><h3 id="forzar-una-actualizacion" tabindex="-1">Forzar una actualización <a class="header-anchor" href="#forzar-una-actualizacion" aria-label="Permalink to &quot;Forzar una actualización&quot;">​</a></h3><p>Ejecute <code>swag2mcp update</code> para limpiar toda la caché y volver a descargar todos los archivos de especificación:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Esto valida la configuración, limpia la caché y descarga todo nuevamente.</p><h3 id="limpiar-la-cache-manualmente" tabindex="-1">Limpiar la caché manualmente <a class="header-anchor" href="#limpiar-la-cache-manualmente" aria-label="Permalink to &quot;Limpiar la caché manualmente&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>Esto elimina todos los archivos de especificación en caché y las respuestas de API guardadas. La próxima vez que inicie el servidor MCP, todas las especificaciones se descargarán nuevamente.</p><h3 id="limpieza-automatica" tabindex="-1">Limpieza automática <a class="header-anchor" href="#limpieza-automatica" aria-label="Permalink to &quot;Limpieza automática&quot;">​</a></h3><p>Cuando se inicia el servidor MCP (<code>swag2mcp mcp</code>), las respuestas de API guardadas con más de 48 horas se eliminan automáticamente. Esto evita que el directorio <code>responses/</code> crezca indefinidamente.</p><h2 id="notas-importantes" tabindex="-1">Notas importantes <a class="header-anchor" href="#notas-importantes" aria-label="Permalink to &quot;Notas importantes&quot;">​</a></h2><ul><li><strong>Los archivos locales en <code>specs/</code> nunca se almacenan en caché</strong> — si edita un archivo de especificación directamente en el directorio <code>specs/</code>, los cambios son inmediatamente visibles sin limpiar la caché</li><li><strong>Las URL remotas siempre se almacenan en caché</strong> — no hay forma de omitir la caché para URL remotas excepto ejecutando <code>swag2mcp update</code> o <code>swag2mcp clean</code></li><li><strong>La caché es local</strong> — se almacena en disco y no se sincroniza entre máquinas. Use <code>swag2mcp export</code> y <code>swag2mcp import</code> para transferir especificaciones entre máquinas</li></ul>`,25)])])}const u=e(s,[["render",t]]);export{m as __pageData,u as default};
